// SSPR world-to-screen projection and debug visualization
float4 clip = mul(float4(WorldPos, 1.0f), View.WorldToClip);
OutDepth = clip.w;
bool inFront = (clip.w > 0.0001f);
float2 ndc = inFront ? (clip.xy / clip.w) : float2(0.0f, 0.0f);
float2 uv = ndc * float2(0.5f, -0.5f) + 0.5f;
bool onScreen = inFront && (uv.x >= 0.0f && uv.x < 1.0f && uv.y >= 0.0f && uv.y < 1.0f);
OutUV = onScreen ? uv : float2(-1.0f, -1.0f);
float depthN = saturate(clip.w / 5000.0f);
float dim = onScreen ? 1.0f : 0.25f;
OutColor = float4(saturate(uv.x) * dim, saturate(uv.y) * dim, depthN * dim, 1.0f);
